// Overload 1: Basic accumulation
public static TSource Aggregate<TSource>(
    this IEnumerable<TSource> source,
    Func<TSource, TSource, TSource> func);

// Overload 2: With seed value
public static TAccumulate Aggregate<TSource, TAccumulate>(
    this IEnumerable<TSource> source,
    TAccumulate seed,
    Func<TAccumulate, TSource, TAccumulate> func);

// Overload 3: With seed and result selector
public static TResult Aggregate<TSource, TAccumulate, TResult>(
    this IEnumerable<TSource> source,
    TAccumulate seed,
    Func<TAccumulate, TSource, TAccumulate> func,
    Func<TAccumulate, TResult> resultSelector);

IList<string> strList = new List<string>() { "One", "Two", "Three", "Four", "Five" };

var commaSeparatedString = strList.Aggregate((s1, s2) => s1 + ", " + s2);

// Result: "One, Two, Three, Four, Five"

IList<Student> studentList = new List<Student>() {
    new Student() { StudentID = 1, StudentName = "John", Age = 13 },
    new Student() { StudentID = 2, StudentName = "Moin", Age = 21 },
    new Student() { StudentID = 3, StudentName = "Bill", Age = 18 },
    new Student() { StudentID = 4, StudentName = "Ram", Age = 20 },
    new Student() { StudentID = 5, StudentName = "Ron", Age = 15 }
};

string commaSeparatedStudentNames = studentList.Aggregate<Student, string>(
    "Student Names: ",  // seed value
    (str, s) => str += s.StudentName + ",");

// Result: "Student Names: John, Moin, Bill, Ram, Ron,"

string commaSeparatedStudentNames = studentList.Aggregate<Student, string, string>(
    String.Empty,                                    // seed value
    (str, s) => str += s.StudentName + ",",          // accumulation
    str => str.Substring(0, str.Length - 1)          // result selector
);

// Result: "John, Moin, Bill, Ram, Ron"

int sumOfStudentsAge = studentList.Aggregate<Student, int>(
    0,
    (totalAge, s) => totalAge += s.Age
);

// Result: 87
